def solve(matrix):
    """Return determinant of a square integer matrix.
    Empty matrix returns 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # verify square (optional)
    for row in matrix:
        if len(row) != n:
            raise ValueError('Non-square matrix')
    # base cases
    if n == 1:
        return matrix[0][0]
    if n == 2:
        return matrix[0][0]*matrix[1][1] - matrix[0][1]*matrix[1][0]
    det = 0
    for col in range(n):
        # compute minor
        minor = [row[:col] + row[col+1:] for row in matrix[1:]]
        det += ((-1) ** col) * matrix[0][col] * solve(minor)
    return det

