def solve(tokens):
    stack = []
    for tok in tokens:
        # check if token is an integer (including negative)
        if tok.lstrip('-').isdigit():
            stack.append(int(tok))
        else:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            elif tok == '/':
                # integer division truncating toward zero
                stack.append(int(a / b))
            else:
                raise ValueError('Invalid token')
    return stack[0] if stack else 0
